import pytest
import torch

from . import base, consts

# (batch_dims, in1_features, in2_features, out_features)
# The bilinear kernel launches a grid of (M, out_features) programs, each
# reducing over in1_features * in2_features. Shapes are kept bounded so the
# program count and per-program reduction stay realistic and the benchmark
# does not stall. CI --level core overrides GenericBenchmark shapes with
# generic 1D/3D defaults, so we subclass base.Benchmark and pin set_shapes.
BILINEAR_SHAPES = [
    (256, 64, 64, 128),
    (512, 128, 128, 256),
    (1024, 64, 48, 96),
    (128, 256, 256, 128),
    (2048, 32, 32, 64),
]


class BilinearBenchmark(base.Benchmark):
    def set_shapes(self, shape_file_path=None):
        self.shapes = BILINEAR_SHAPES

    def get_case_iter(self, dtype):
        ordinal = 0
        for m, in1, in2, out in self.shapes:
            yield self._case_from_plan(
                dtype,
                ordinal,
                base.BenchmarkCasePlan(
                    shape={"input1": [m, in1]},
                    params={},
                    builder_args=(m, in1, in2, out),
                ),
            )
            ordinal += 1

    def build_inputs(self, case):
        plan = case.builder_args[0]
        m, in1, in2, out = plan.builder_args
        cur_dtype = case.dtype
        input1 = torch.randn((m, in1), dtype=cur_dtype, device=self.device)
        input2 = torch.randn((m, in2), dtype=cur_dtype, device=self.device)
        weight = torch.randn((out, in1, in2), dtype=cur_dtype, device=self.device)
        bias = torch.randn((out,), dtype=cur_dtype, device=self.device)
        return input1, input2, weight, bias


@pytest.mark.bilinear
def test_bilinear():
    bench = BilinearBenchmark(
        op_name="bilinear",
        torch_op=torch.nn.functional.bilinear,
        dtypes=consts.FLOAT_DTYPES,
    )
    bench.run()
